-- Course master (docs/designs/course-master/course-master.md): descriptive, duration and flag fields on app.course
-- (DD-1), the centre classes a course may be sold at (DD-2), named checks, RLS and column grants. The DDL below the
-- header was generated by prisma migrate diff (R4); checks, RLS and grants are hand-written.

-- AlterTable
ALTER TABLE "app"."course" ADD COLUMN     "capacity" INTEGER,
ADD COLUMN     "department" TEXT,
ADD COLUMN     "display_name" TEXT,
ADD COLUMN     "duration_days" INTEGER,
ADD COLUMN     "duration_hours" INTEGER,
ADD COLUMN     "duration_months" INTEGER,
ADD COLUMN     "duration_type" TEXT,
ADD COLUMN     "duration_weeks" INTEGER,
ADD COLUMN     "exam_min_days" INTEGER,
ADD COLUMN     "internship_keltron" BOOLEAN NOT NULL DEFAULT false,
ADD COLUMN     "it_magic" BOOLEAN NOT NULL DEFAULT false,
ADD COLUMN     "keltron" BOOLEAN NOT NULL DEFAULT false,
ADD COLUMN     "keltron_share" DECIMAL(5,2),
ADD COLUMN     "marklist_required" BOOLEAN NOT NULL DEFAULT false,
ADD COLUMN     "materials_required" BOOLEAN NOT NULL DEFAULT false,
ADD COLUMN     "no_reg_fee" BOOLEAN NOT NULL DEFAULT false,
ADD COLUMN     "selected" BOOLEAN NOT NULL DEFAULT false,
ADD COLUMN     "sort_order" INTEGER NOT NULL DEFAULT 0,
ADD COLUMN     "visible" BOOLEAN NOT NULL DEFAULT true;

-- CreateTable
CREATE TABLE "app"."course_centre_class" (
    "course_id" INTEGER NOT NULL,
    "centre_class_id" INTEGER NOT NULL,

    CONSTRAINT "course_centre_class_pkey" PRIMARY KEY ("course_id","centre_class_id")
);

-- AddForeignKey
ALTER TABLE "app"."course_centre_class" ADD CONSTRAINT "course_centre_class_course_id_fkey" FOREIGN KEY ("course_id") REFERENCES "app"."course"("id") ON DELETE RESTRICT ON UPDATE RESTRICT;

-- AddForeignKey
ALTER TABLE "app"."course_centre_class" ADD CONSTRAINT "course_centre_class_centre_class_id_fkey" FOREIGN KEY ("centre_class_id") REFERENCES "app"."centre_class"("id") ON DELETE RESTRICT ON UPDATE RESTRICT;

-- ---------- Named checks (the app's rules in src/server/catalogue.ts are at least as strict) ----------
alter table app.course add constraint course_display_name_check
  check (display_name = btrim(display_name) and char_length(display_name) between 1 and 200);
alter table app.course add constraint course_department_check
  check (department = btrim(department) and char_length(department) between 1 and 100);
alter table app.course add constraint course_duration_type_check check (duration_type in ('MONTH', 'WEEK', 'DAY', 'NA'));
alter table app.course add constraint course_duration_months_check check (duration_months between 0 and 120);
alter table app.course add constraint course_duration_weeks_check check (duration_weeks between 0 and 520);
alter table app.course add constraint course_duration_days_check check (duration_days between 0 and 3650);
alter table app.course add constraint course_duration_hours_check check (duration_hours between 0 and 10000);
alter table app.course add constraint course_capacity_check check (capacity between 1 and 100000);
alter table app.course add constraint course_exam_min_days_check check (exam_min_days between 0 and 3650);
alter table app.course add constraint course_sort_order_check check (sort_order between 0 and 100000);
-- DD-6, DD-11: a KELTRON course has a share of 0-100; any other course has none. "is not null" is needed: a null
-- share makes "between" null, and a check that is null passes.
alter table app.course add constraint course_keltron_share_check check (
  (keltron and keltron_share is not null and keltron_share between 0 and 100) or (not keltron and keltron_share is null));

-- ---------- RLS: setup-table policy (0009, 0012); a link is deleted, not deactivated ----------
alter table app.course_centre_class enable row level security;
alter table app.course_centre_class force row level security;
create policy setup_select on app.course_centre_class for select using (true);
create policy setup_insert on app.course_centre_class for insert
  with check ((select app.has_permission('catalogue.manage', null)));
create policy setup_delete on app.course_centre_class for delete
  using ((select app.has_permission('catalogue.manage', null)));

-- ---------- Grants (Z1; the table-level select and insert on app.course stay as 0012 set them) ----------
grant select, insert, delete on app.course_centre_class to gems_app;
grant update (display_name, department, duration_type, duration_months, duration_weeks, duration_days, duration_hours,
  capacity, exam_min_days, sort_order, visible, materials_required, marklist_required, no_reg_fee, it_magic, keltron,
  internship_keltron, selected, keltron_share) on app.course to gems_app;
